// ---- figures pròpies ----
function svgCapses(){
 const caixa=(x,y,w,h,f,v,t,ty)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="${f}" stroke="${v}" stroke-width="2.5"/><text x="${x+14}" y="${y+ty}" font-size="15" font-weight="800" fill="${v}">${t}</text>`;
 let s=`<svg viewBox="0 0 440 300" width="100%" style="max-width:480px" font-family="Nunito,Arial,sans-serif">`;
 s+=caixa(10,10,420,256,"#f5f3ff","#6d28d9","CATALUNYA",26);
 s+=caixa(34,42,372,212,"#eff6ff","#1d4ed8","BARCELONA",26);
 s+=caixa(60,74,320,166,"#ecfdf5","#047857","ANOIA",26);
 s+=caixa(88,108,150,56,"#fff7ed","#c2410c","IGUALADA",34);
 s+=`<circle cx="226" cy="136" r="5" fill="#dc2626"/>`;
 s+=`<rect x="250" y="108" width="112" height="56" rx="14" fill="#fff" stroke="#94a3b8" stroke-dasharray="5,4" stroke-width="2"/><text x="306" y="141" font-size="13" text-anchor="middle" fill="#475569">Òdena</text>`;
 s+=`<rect x="88" y="176" width="274" height="50" rx="14" fill="#fff" stroke="#94a3b8" stroke-dasharray="5,4" stroke-width="2"/><text x="225" y="206" font-size="13" text-anchor="middle" fill="#475569">Vilanova del Camí, i més pobles…</text>`;
 return s+`<text x="220" y="290" font-size="12" text-anchor="middle" font-weight="700" fill="#334155">Capses dins de capses (esquema, no és un mapa) · ● capital</text></svg>`;
}
// ---- joc MAPA interactiu (tipus custom): explora · on és? · quina capital? ----
// Les formes surten de const MAPA (al final del fitxer, generat amb dades oficials de límits municipals).
const DEMCOL={B:["#dbeafe","#1d4ed8"],G:["#dcfce7","#15803d"],L:["#fef3c7","#b45309"],T:["#fce7f3","#be185d"]};
const DEMIC={B:"🏙️",G:"🌋",L:"⛰️",T:"🌊"};
let MP={mode:"explora",dem:"",num:true,veure:"tot",revela:new Set()}; // veure: tot · com (només comarca) · cap (només capital)
const mpC=n=>COM[n-1]; // [n,nom,capital,dem]
const MPLA=["Selva","Segarra","Noguera","Cerdanya","Conca de Barberà","Garrotxa","Terra Alta","Ribera d'Ebre","Vall d'Aran"];
const mpArtP=nom=>nom==="Garrigues"?"les Garrigues":nom==="Osona"?"Osona":MPLA.includes(nom)?"la "+nom:/^[AEIOUÀÈÉÍÒÓÚ]/i.test(nom)?"l'"+nom:"el "+nom; // el Bages, l'Anoia, la Selva
const mpDe=nom=>{const a=mpArtP(nom);return a.startsWith("el ")?"del "+nom:/^[AEIOUÀÈÉÍÒÓÚ]/i.test(a)?"d'"+a:"de "+a}; // del Bages, de l'Anoia, d'Osona
const mpMaj=t=>t[0].toUpperCase()+t.slice(1);
function mpCss(){if(document.getElementById("mpCss"))return;const s=document.createElement("style");s.id="mpCss";s.textContent=`
.mp-modes{display:flex;gap:6px;margin:0 0 10px}.mp-modes button{flex:1;border:0;border-radius:14px;padding:10px 4px;font-weight:900;font-size:14.5px;cursor:pointer;background:#fff;color:var(--suau);box-shadow:var(--om)}
.mp-modes button.on{background:var(--fosc);color:#fff}
.mp-filtre{display:flex;flex-wrap:wrap;gap:4px;margin:0 0 10px}.mp-filtre .chip{margin:0;padding:6px 10px;font-size:13.5px}
.mp-enun{font-weight:900;font-size:18px;min-height:28px;margin:0 0 8px;text-align:center}.mp-enun b{color:#c2410c}
.mp-wrap{position:relative;overflow:auto;max-height:78vh;border-radius:14px;background:#f8fafc;touch-action:pan-x pan-y}
.mp-svg{user-select:none;-webkit-user-select:none;display:block;width:100%;max-width:620px;margin:0 auto;height:auto;transition:width .2s}
.mp-wrap.gran .mp-svg{width:230%;max-width:none}
.mp-c{stroke:#64748b;stroke-width:.7;cursor:pointer;transition:fill .15s}.mp-c:hover,.mp-c.hov{filter:brightness(.93);stroke:#0f172a;stroke-width:1.4}
.mp-c.sel{stroke:#0f172a;stroke-width:2}.mp-c.ok{fill:#4ade80!important}.mp-c.ko{fill:#f87171!important}
.mp-c.mira{fill:#fb923c;stroke:#7c2d12;stroke-width:2;animation:mpBat .9s steps(2,jump-none) infinite}@keyframes mpBat{0%{fill:#fb923c}100%{fill:#ffedd5}}
.mp-c.sol{fill:#22c55e;stroke:#052e16;stroke-width:3;animation:mpSol .4s steps(2,jump-none) infinite}@keyframes mpSol{0%{fill:#22c55e}100%{fill:#ffffff}}
.opt.sol{animation:mpOpt .4s steps(2,jump-none) 6}@keyframes mpOpt{0%{background:#dcfce7}100%{background:#fff}}
.mp-lab circle{fill:#fff;stroke:#94a3b8;stroke-width:.6}.mp-lab text{font:800 8.5px Nunito,Arial,sans-serif;fill:#0f172a;text-anchor:middle;dominant-baseline:central}
.mp-tip{position:absolute;pointer-events:none;background:#0f172a;color:#fff;font-weight:800;font-size:13.5px;padding:6px 10px;border-radius:10px;white-space:nowrap;transform:translate(-50%,-125%);display:none;z-index:3}
.mp-eines{display:flex;gap:8px;justify-content:center;margin-top:10px;flex-wrap:wrap}.mp-eines .btn{padding:8px 12px;font-size:14px}
.mp-info{margin:0 0 10px;box-sizing:border-box;padding:12px 14px;border-radius:14px;border:2px solid var(--vora);background:#fff;min-height:58px}
.mp-info h3{margin:0 0 4px;font-size:19px}.mp-info p{margin:2px 0;font-weight:700}
.mp-opts{display:flex;flex-direction:column;gap:8px;margin:0 0 10px}
.mp-modes{flex-wrap:wrap}.mp-modes button{flex:1 1 18%;min-width:104px}
.mp-tip{text-align:center;line-height:1.3;font-size:14.5px;box-shadow:0 6px 16px #0f172a55}.mp-tip b{display:block}.mp-tip span{display:block;color:#fde68a;font-weight:800}
.mp-tip.sota{transform:translate(-50%,28%)}
.mp-crono{height:12px;background:#e2e8f0;border-radius:8px;overflow:hidden;margin:0 0 8px}.mp-crono i{display:block;height:100%;width:100%;border-radius:8px;background:linear-gradient(90deg,#22c55e,#facc15)}.mp-crono i.poc{background:linear-gradient(90deg,#ef4444,#f97316)}
.mp-marc{display:flex;justify-content:space-between;gap:8px;font-weight:900;font-size:17px;margin:0 0 8px}#mpCrC{color:#ea580c}
.mp-opts.mp-4{display:grid;grid-template-columns:1fr 1fr;gap:8px}.mp-4 .opt{margin:0;justify-content:center;text-align:center;font-weight:900}
.mp-llegenda{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;font-size:13px;font-weight:800;color:var(--suau);margin-top:8px}.mp-llegenda i{display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:4px;vertical-align:-1px;border:1px solid #94a3b8}`;document.head.appendChild(s)}
function mpSvg(){
 const c=MAPA.c.map(([n,d])=>`<path class="mp-c" data-n="${n}" d="${d}" fill="${DEMCOL[mpC(n)[3]][0]}"/>`).join("");
 const caps=MAPA.c.map(([n,,,,cs])=>cs.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="2.3" fill="#b91c1c" stroke="#fff" stroke-width=".7"/>`).join("")).join("");
 const lab=MAPA.c.map(([n,,x,y,cs])=>{if(cs.some(([a,b])=>Math.hypot(a-x,b-y)<9))y-=10;return `<g class="mp-lab"><circle cx="${x}" cy="${y}" r="7.5"/><text x="${x}" y="${y}">${n}</text></g>`}).join("");
 return `<svg class="mp-svg" viewBox="0 0 ${MAPA.w} ${MAPA.h}" role="img" aria-label="Mapa interactiu de les 43 comarques de Catalunya">
 <g id="mpCom">${c}</g><path d="${MAPA.prov}" fill="none" stroke="#1e293b" stroke-width="2" stroke-linejoin="round" pointer-events="none"/>
 <path d="${MAPA.vora}" fill="none" stroke="#334155" stroke-width="1.2" pointer-events="none"/>
 <g pointer-events="none">${caps}</g><g id="mpLabs" pointer-events="none"${MP.num?"":' style="display:none"'}>${lab}</g></svg>`}
function jocMapa(j){
 aturaSeg();MP.fi=0;mpCss();MP.j=j;MP.vist=MP.vist||new Set();if(MP.modeAnt!==MP.mode){MP.num=MP.mode==="explora";MP.modeAnt=MP.mode}
 app.innerHTML=`<h2 class="sec">${j.enunciat||j.titol}</h2>
 <div class="mp-modes">${[["explora","🔍 Explora"],["onEs","📍 On és?"],["capital","🏛️ Capital"],["quiEs","🎯 De qui és?"],["contra","⏱ Contrarellotge"]].map(([m,t])=>`<button class="${MP.mode===m?"on":""}" onclick="MP.mode='${m}';jocMapa(MP.j)">${t}</button>`).join("")}</div>
 <div class="mp-filtre">${[["","Totes (43)"],["B","Barcelona"],["G","Girona"],["L","Lleida"],["T","Tarragona"]].map(([d,t])=>`<span class="chip ${MP.dem===d?"sel":""}" onclick="MP.dem='${d}';jocMapa(MP.j)">${d?DEMIC[d]+" ":""}${t}</span>`).join("")}</div>
 <div class="box" style="padding:14px"><div class="mp-enun" id="mpEnun"></div><div id="mpZona"></div>
 <div class="mp-wrap" id="mpWrap">${mpSvg()}<div class="mp-tip" id="mpTip"></div></div>
 <div class="mp-llegenda">${"BGLT".split("").map(d=>`<span><i style="background:${DEMCOL[d][0]}"></i>${DEMNOM[d]}</span>`).join("")}<span><i style="background:#b91c1c;border-radius:50%"></i>capital</span></div>
 <div class="mp-eines"><button class="btn sec" onclick="MP.num=!MP.num;document.getElementById('mpLabs').style.display=MP.num?'':'none';this.textContent=MP.num?'🔢 Amaga números':'🔢 Mostra números'">${MP.num?"🔢 Amaga números":"🔢 Mostra números"}</button>
 <button class="btn sec" onclick="const w=document.getElementById('mpWrap');w.classList.toggle('gran');this.textContent=w.classList.contains('gran')?'🔎 Fes-lo petit':'🔍 Fes-lo gran'">🔍 Fes-lo gran</button></div>
 </div><div id="zona"></div>`;
 const tip=document.getElementById("mpTip"),wrap=document.getElementById("mpWrap");
 // en mode joc, les comarques fora de la demarcació triada queden apagades
 document.querySelectorAll(".mp-c").forEach(p=>{const n=+p.dataset.n;
  if(MP.dem&&mpC(n)[3]!==MP.dem)p.style.opacity=".35";
  p.addEventListener("pointermove",e=>{if(e.pointerType!=="mouse")return;const r=wrap.getBoundingClientRect();
   tip.innerHTML=mpTipHtml(n);tip.classList.toggle("sota",e.clientY-r.top<80);
   tip.style.left=(e.clientX-r.left+wrap.scrollLeft)+"px";tip.style.top=(e.clientY-r.top+wrap.scrollTop)+"px";tip.style.display="block";
   if(MP.mode==="explora")mpInfo(n,true)});
  p.addEventListener("pointerleave",()=>{tip.style.display="none"});
  p.addEventListener("click",()=>{mpToca(n,p);const ara=Date.now();if(MP.ultToc&&MP.ultToc.n===n&&ara-MP.ultToc.t<450){MP.ultToc=null;mpDestapa(n)}else MP.ultToc={n,t:ara}})});
 ({explora:mpExplora,onEs:mpOnEs,capital:mpCapital,quiEs:mpQui,contra:mpContra})[MP.mode]();
}
// què diu l'etiqueta en passar el ratolí: a Explora, comarca i capital; als jocs, només el que no regala la resposta
function mpTipHtml(n){const [,nom,cap]=mpC(n),fet=MP.fet&&MP.fet.has(n),tot=`<b>${n} · ${nom}</b><span>🏛️ ${cap}</span>`;
 if(MP.mode==="explora"){const vist=MP.revela.has(n);
  if(MP.veure==="com")return `<b>${n} · ${nom}</b><span>${vist?`🏛️ ${cap}`:"🖱️🖱️ doble clic: la capital"}</span>`;
  if(MP.veure==="cap")return `<b>${vist?`${n} · ${nom}`:"🖱️🖱️ doble clic: la comarca"}</b><span>🏛️ ${cap}</span>`;
  return tot}
 if(MP.mode==="onEs"||MP.mode==="quiEs")return fet?tot:`<b>Aquesta? 🤔</b>`;
 return fet?tot:`<b>${n} · ${nom}</b>`}
function mpTip(n){const [,nom,cap]=mpC(n);return MP.veure==="com"?`${n} · ${nom}`:MP.veure==="cap"?`🏛️ ${cap}`:`${n} · ${nom} · 🏛️ ${cap}`}
function mpVeure(v){MP.veure=v;MP.revela=new Set();const s=document.querySelector(".mp-c.sel");mpExplora();if(s)mpInfo(+s.dataset.n,true)}
const mpLlista=()=>COM.filter(c=>!MP.dem||c[3]===MP.dem).map(c=>c[0]);
function mpExplora(){
 document.getElementById("mpEnun").innerHTML=MP.veure==="tot"?`Passa el ratolí o el dit per sobre d'una comarca`:`Endevina-la! Fes <b>doble clic</b> a la comarca per veure la resposta`;
 document.getElementById("mpZona").innerHTML=`<div class="mp-veure mp-filtre" style="justify-content:center"><span class="prog" style="align-self:center">👁️ Veure:</span>${[["tot","Comarca i capital"],["com","Només comarca"],["cap","Només capital"]].map(([v,t])=>`<span class="chip ${MP.veure===v?"sel":""}" data-v="${v}" onclick="mpVeure('${v}')">${t}</span>`).join("")}</div><div class="mp-info" id="mpInfo" style="min-height:118px"><p style="color:var(--suau)">👆 Toca una comarca per veure el nom, la capital i la demarcació.</p></div><p class="prog" id="mpVist" style="text-align:center;margin:-4px 0 8px"></p>`;
 mpVist()}
// ---- doble clic a Explora: surt la resposta que falta (la capital o la comarca) ----
function mpDestapa(n){if(MP.mode!=="explora"||MP.veure==="tot")return;MP.revela.add(n);mpInfo(n,false);so("gir");
 const t=document.getElementById("mpTip");if(t&&t.style.display==="block")t.innerHTML=mpTipHtml(n)}
function mpVist(){const L=mpLlista(),v=L.filter(n=>MP.vist.has(n)).length;const e=document.getElementById("mpVist");if(e)e.innerHTML=`👀 N'has mirat ${v} de ${L.length}${v===L.length?" · 🎉 totes! Ara prova «📍 On és?»":""}`}
function mpInfo(n,nomesHover){const [,nom,cap,d]=mpC(n);const e=document.getElementById("mpInfo");if(!e)return;
 document.querySelectorAll(".mp-c.sel").forEach(p=>p.classList.remove("sel"));document.querySelector(`.mp-c[data-n="${n}"]`).classList.add("sel");
 const caps=cap.includes(" i Terrassa")?`<b>Sabadell</b> i <b>Terrassa</b> (en té dues!)`:`<b>${cap}</b>`;
 const txt=`${nom}. Capital: ${cap}. Demarcació de ${DEMNOM[d]}.`;
 const vist=MP.revela.has(n),tapa=t=>vist?t:`<span class="mp-tapa" onclick="this.outerHTML=this.dataset.t" data-t="${t.replace(/"/g,"&quot;")}" style="background:#e2e8f0;border-radius:8px;padding:0 10px;cursor:pointer;color:var(--suau)">❓ doble clic a la comarca (o toca aquí)</span>`;
 const titol=MP.veure==="cap"?`${n} · ${tapa(nom)}`:`${n} · ${nom}`,capT=MP.veure==="com"?tapa(caps):caps;
 e.style.borderColor=DEMCOL[d][1];e.innerHTML=`<h3 style="color:${DEMCOL[d][1]}">${titol} ${MP.veure==="tot"?btEscolta(txt,""):""}</h3><p>🏛️ Capital: ${capT}</p><p>${DEMIC[d]} Demarcació de ${DEMNOM[d]}</p>${n===21?`<p style="color:var(--suau);font-size:13px;margin:0">⭐ La més nova (2023): abans era part d'Osona.</p>`:""}`;
 if(!nomesHover){MP.vist.add(n);mpVist()}}
function mpToca(n,p){
 if(MP.mode==="explora"){mpInfo(n,false);so("ok");return}
 if(MP.dem&&mpC(n)[3]!==MP.dem)return;
 if(MP.mode==="onEs")return mpRespon(n,p);
 if(MP.mode==="quiEs")return mpRespQui(n,p);
}
// ---- 📍 On és? ----
function mpRonda(max){const L=barreja(mpLlista().slice());return L.slice(0,Math.min(max,L.length))}
function mpOnEs(){MP.r=mpRonda(15);MP.k=0;MP.enc=0;MP.err=0;MP.int=0;MP.fet=new Set();mpPregOnEs()}
function mpPregOnEs(){if(MP.k>=MP.r.length)return mpFi();const n=MP.r[MP.k];MP.int=0;
 document.getElementById("mpEnun").innerHTML=`📍 On és ${mpArtP(mpC(n)[1])}? <small class="prog">(${MP.k+1}/${MP.r.length})</small>`;
 document.getElementById("mpZona").innerHTML=`<div class="mp-info" id="mpInfo"><p style="color:var(--suau)">Toca la comarca al mapa. Si falles, et diré quina has tocat.</p></div>`}
function mpRespon(n,p){const bona=MP.r[MP.k];if(MP.mode!=="onEs"||MP.bloc||MP.fet.has(n))return;
 const e=document.getElementById("mpInfo");
 if(n===bona){p.classList.add("ok");MP.fet.add(n);if(!MP.int){MP.enc++;suma(JOCSTAR)}so("ok");
  e.style.borderColor="#22c55e";e.innerHTML=`<p>✅ Sí! ${n} · <b>${mpC(n)[1]}</b>, capital <b>${mpC(n)[2]}</b>.</p>`;MP.k++;MP.bloc=1;setTimeout(()=>{MP.bloc=0;mpPregOnEs()},1100);return}
 MP.int++;if(MP.int===1)MP.err++;so("ko");p.classList.add("ko");setTimeout(()=>p.classList.remove("ko"),700);
 e.style.borderColor="#f97316";
 if(MP.int<2){e.innerHTML=`<p>❌ Aquesta és ${mpArtP(mpC(n)[1])}. Torna-ho a provar!</p>`;return}
 const q=mpSol(bona,3000);MP.fet.add(bona);
 e.innerHTML=`<p>❌ Aquesta és ${mpArtP(mpC(n)[1])}. ${mpMaj(mpArtP(mpC(bona)[1]))} és la que fa pampallugues en <b style="color:#15803d">verd</b> (capital: ${mpC(bona)[2]}).</p>`;
 MP.k++;MP.bloc=1;setTimeout(()=>{q.classList.add("ko");MP.bloc=0;mpPregOnEs()},3000)}
// ---- 🏛️ Quina capital? ----
function mpCapital(){MP.r=mpRonda(10);MP.k=0;MP.enc=0;MP.err=0;mpPregCap()}
function mpPregCap(){document.querySelectorAll(".mp-c.mira").forEach(p=>p.classList.remove("mira"));if(MP.k>=MP.r.length)return mpFi();
 const n=MP.r[MP.k],[,nom,cap,d]=mpC(n);document.querySelector(`.mp-c[data-n="${n}"]`).classList.add("mira");
 const alt=barreja(COM.filter(c=>c[3]===d&&c[0]!==n).map(c=>c[2])).slice(0,2),ops=barreja([cap,...alt]);
 document.getElementById("mpEnun").innerHTML=`🏛️ Quina és la capital ${mpDe(nom)}? <small class="prog">(${MP.k+1}/${MP.r.length})</small>`;
 document.getElementById("mpZona").innerHTML=`<div class="mp-opts">${ops.map(o=>`<button class="opt" data-c="${o.replace(/"/g,"&quot;")}" onclick="mpTriaCap(this)"><span>${o}</span></button>`).join("")}</div><div id="mpInfo"></div><p class="prog" style="text-align:center;margin:0 0 8px">👇 La comarca és la que fa pampallugues al mapa 🟠</p>`}
function mpTriaCap(b){if(MP.bloc)return;const n=MP.r[MP.k],[,nom,cap]=mpC(n),ok=b.dataset.c===cap;MP.bloc=1;
 document.querySelectorAll(".mp-opts .opt").forEach(o=>{if(o.dataset.c===cap)o.classList.add("ok")});
 const p=document.querySelector(`.mp-c[data-n="${n}"]`);p.classList.remove("mira");
 if(ok){MP.enc++;suma(JOCSTAR);so("ok");p.classList.add("ok")}else{MP.err++;so("ko");b.classList.add("ko");mpSol(n,2600);document.querySelectorAll(".mp-opts .opt.ok").forEach(o=>o.classList.add("sol"))}
 document.getElementById("mpInfo").innerHTML=`<div class="fb ${ok?"ok":"ko"}">${ok?"✅ Molt bé!":"❌ No."} La capital ${mpDe(nom)} és <b>${cap}</b>.</div>`;
 MP.k++;setTimeout(()=>{MP.bloc=0;mpPregCap()},ok?1100:2600)}
// ---- 🎯 De qui és? Et dic la capital i toques la comarca al mapa ----
const mpEsCap=cap=>cap.includes(" i ")?`<b>${cap}</b> són les capitals`:`<b>${mpMaj(cap)}</b> és la capital`;
function mpQui(){MP.r=mpRonda(10);MP.k=0;MP.enc=0;MP.err=0;MP.int=0;MP.fet=new Set();mpPregQui()}
function mpPregQui(){if(MP.k>=MP.r.length)return mpFi();const n=MP.r[MP.k];MP.int=0;
 document.getElementById("mpEnun").innerHTML=`🎯 ${mpEsCap(mpC(n)[2])} de quina comarca? <small class="prog">(${MP.k+1}/${MP.r.length})</small>`;
 document.getElementById("mpZona").innerHTML=`<div class="mp-info" id="mpInfo"><p style="color:var(--suau)">Toca la comarca al mapa. Si t'equivoques, et diré quina has tocat i quina capital té.</p></div>`}
function mpRespQui(n,p){const bona=MP.r[MP.k];if(MP.mode!=="quiEs"||MP.bloc||MP.fet.has(n))return;
 const e=document.getElementById("mpInfo"),[,nb,cb]=mpC(bona),[,nn,cn]=mpC(n);
 if(n===bona){p.classList.add("ok");MP.fet.add(n);if(!MP.int){MP.enc++;suma(JOCSTAR)}so("ok");e.style.borderColor="#22c55e";
  e.innerHTML=`<p>✅ Sí! ${mpEsCap(cb)} ${mpDe(nb)} (${n}).</p>`;MP.k++;MP.bloc=1;setTimeout(()=>{MP.bloc=0;if(MP.mode==="quiEs")mpPregQui()},1200);return}
 MP.int++;if(MP.int===1)MP.err++;so("ko");p.classList.add("ko");setTimeout(()=>p.classList.remove("ko"),700);e.style.borderColor="#f97316";
 if(MP.int<2){e.innerHTML=`<p>❌ Aquesta és ${mpArtP(nn)}, i la seva capital és <b>${cn}</b>. Torna-ho a provar!</p>`;return}
 const q=mpSol(bona,3000);MP.fet.add(bona);
 e.innerHTML=`<p>❌ Aquesta és ${mpArtP(nn)} (capital: ${cn}). La resposta era ${mpArtP(nb)}: és la que fa pampallugues en <b style="color:#15803d">verd</b>.</p>`;
 MP.k++;MP.bloc=1;setTimeout(()=>{q.classList.add("ko");MP.bloc=0;if(MP.mode==="quiEs")mpPregQui()},3000)}
// ---- ⏱ Contrarellotge: 60 segons per encertar tantes capitals com puguis ----
const MP_T=60;
const mpRecKey=()=>"bn_mp_rec_"+(S.nom||"").trim().toLowerCase();
function mpRec(){try{return +localStorage.getItem(mpRecKey())||0}catch(e){return 0}}
function mpContra(){MP.fi=0;MP.enc=0;MP.err=0;MP.r=[];MP.k=0;
 document.getElementById("mpEnun").innerHTML=`⏱ Contrarellotge: ${MP_T} segons!`;
 document.getElementById("mpZona").innerHTML=`<div class="mp-info"><p>La comarca fa pampallugues al mapa 🟠. Tria la seva capital tan ràpid com puguis. Si n'encertes 3 seguides, fas <b>combo</b> 🔥.</p><p>🏆 El teu rècord: <b>${mpRec()}</b> capitals</p></div><div class="fila" style="margin:0 0 10px"><button class="btn verd" onclick="mpContraVa()">Comença ▶</button></div>`}
function mpContraVa(){aturaSeg();MP.enc=0;MP.err=0;MP.combo=0;MP.bloc=0;MP.fi=Date.now()+MP_T*1000;MP.pila=barreja(mpLlista().slice());
 document.getElementById("mpZona").innerHTML=`<div class="mp-crono"><i id="mpCrI"></i></div><div class="mp-marc"><span id="mpCrS">⏱ ${MP_T}</span><span id="mpCrC"></span><span id="mpCrE">✅ 0</span></div><div class="mp-opts mp-4" id="mpOpts"></div>`;
 temp=setInterval(()=>{const q=Math.max(0,MP.fi-Date.now()),i=document.getElementById("mpCrI");if(!i||!MP.fi){aturaSeg();return}
  i.style.width=(q/(MP_T*10))+"%";document.getElementById("mpCrS").textContent="⏱ "+Math.ceil(q/1000);if(q<=10000)i.classList.add("poc");if(q<=0)mpContraFi()},100);
 mpContraPreg()}
function mpContraPreg(){document.querySelectorAll(".mp-c.mira").forEach(p=>p.classList.remove("mira"));if(!MP.pila.length)MP.pila=barreja(mpLlista().slice());
 const n=MP.pila.pop(),[,nom,cap,d]=mpC(n);MP.cn=n;document.querySelector(`.mp-c[data-n="${n}"]`).classList.add("mira");
 const mateixa=barreja(COM.filter(c=>c[3]===d&&c[0]!==n).map(c=>c[2])),altres=barreja(COM.filter(c=>c[3]!==d).map(c=>c[2]));
 const ops=barreja([cap,...mateixa.slice(0,2),altres[0]]);
 document.getElementById("mpEnun").innerHTML=`⏱ Quina és la capital ${mpDe(nom)}?`;
 document.getElementById("mpOpts").innerHTML=ops.map(o=>`<button class="opt" data-c="${o.replace(/"/g,"&quot;")}" onclick="mpContraTria(this)"><span>${o}</span></button>`).join("")}
function mpContraTria(b){if(MP.bloc||!MP.fi)return;const n=MP.cn,cap=mpC(n)[2],ok=b.dataset.c===cap,p=document.querySelector(`.mp-c[data-n="${n}"]`);p.classList.remove("mira");
 if(ok){MP.enc++;MP.combo++;if(MP.enc<=15)suma(JOCSTAR);so("ok");b.classList.add("ok");p.classList.add("ok");setTimeout(()=>p.classList.remove("ok"),900)}
 else{MP.err++;MP.combo=0;so("ko");b.classList.add("ko");mpSol(n,900);document.querySelectorAll("#mpOpts .opt").forEach(o=>{if(o.dataset.c===cap)o.classList.add("ok","sol")})}
 document.getElementById("mpCrE").textContent="✅ "+MP.enc;document.getElementById("mpCrC").textContent=MP.combo>=3?`🔥 COMBO ×${MP.combo}`:"";
 MP.bloc=1;setTimeout(()=>{MP.bloc=0;if(MP.fi&&MP.mode==="contra")mpContraPreg()},ok?280:1100)}
function mpContraFi(){if(!MP.fi)return;MP.fi=0;aturaSeg();document.querySelectorAll(".mp-c.mira").forEach(p=>p.classList.remove("mira"));
 const rec=mpRec(),nou=MP.enc>rec;if(nou)try{localStorage.setItem(mpRecKey(),String(MP.enc))}catch(e){}
 document.getElementById("mpEnun").innerHTML=`⏱ Temps! ${MP.enc} capital${MP.enc===1?"":"s"} encertad${MP.enc===1?"a":"es"}${nou?" · 🏆 NOU RÈCORD!":` · el teu rècord: ${rec}`}`;
 document.getElementById("mpZona").innerHTML=`<div class="fila" style="margin:0 0 10px"><button class="btn verd" onclick="mpContraVa()">Torna-hi ▶</button></div>`;
 if(MP.enc+MP.err)fiJoc(MP.j,MP.enc,MP.err)}
function mpSol(n,ms){const q=document.querySelector(`.mp-c[data-n="${n}"]`);if(!q)return q;q.parentNode.appendChild(q);q.classList.remove("mira","ko");q.classList.add("sol");setTimeout(()=>q.classList.remove("sol"),ms);return q}
function mpFi(){document.getElementById("mpEnun").innerHTML=`🏁 Ronda acabada: ${MP.enc} de ${MP.r.length} a la primera`;document.getElementById("mpZona").innerHTML="";fiJoc(MP.j,MP.enc,MP.err)}
// per a la prova automàtica (motor/prova.js): juga totes dues rondes encertant-ho tot
function provaMapa(j){MP.mode="onEs";MP.dem="";jocMapa(j);for(let i=0;i<MP.r.length;i++){MP.bloc=0;const n=MP.r[MP.k];mpRespon(n,document.querySelector(`.mp-c[data-n="${n}"]`));MP.bloc=0;mpPregOnEs()}
 MP.mode="capital";jocMapa(j);for(let i=0;i<MP.r.length;i++){MP.bloc=0;const cap=mpC(MP.r[MP.k])[2];mpTriaCap([...document.querySelectorAll(".mp-opts .opt")].find(o=>o.dataset.c===cap));MP.bloc=0;mpPregCap()}
 MP.mode="quiEs";jocMapa(j);for(let i=0;i<MP.r.length;i++){MP.bloc=0;const n=MP.r[MP.k];mpRespQui(n,document.querySelector(`.mp-c[data-n="${n}"]`));MP.bloc=0;mpPregQui()}
 MP.mode="contra";jocMapa(j);mpContraVa();for(let i=0;i<5;i++){MP.bloc=0;const cap=mpC(MP.cn)[2];mpContraTria([...document.querySelectorAll("#mpOpts .opt")].find(o=>o.dataset.c===cap));MP.bloc=0;mpContraPreg()}
 const okContra=MP.enc===5;mpContraFi();
 MP.mode="explora";return okContra||"contrarellotge: no ha comptat els encerts"}

